    constexpr std::array<uint8_t,52> wave={'R','I','F','F',44,0,0,0,'W','A','V','E','f','m','t',' ',16,0,0,0,1,0,1,0,0x40,0x1f,0,0,0x80,0x3e,0,0,2,0,16,0,'d','a','t','a',8,0,0,0,0,0,0xff,0x7f,0,0,1,0x80};
    AudioLoadResult loaded=LoadWave(wave);if(!loaded||loaded.clip.sampleRate!=8000||loaded.clip.channels!=1||loaded.clip.bitsPerSample!=16||loaded.clip.FrameCount()!=4||std::abs(loaded.clip.DurationSeconds()-.0005f)>.00001f){std::cerr<<"PCM WAVE parsing failed\n";return 1;}
    constexpr std::size_t LargeSampleBytes=4*1024*1024;std::vector<uint8_t> ownedWave(wave.begin(),wave.begin()+44);ownedWave.resize(44+LargeSampleBytes);auto writeU32=[&](std::size_t offset,uint32_t value){for(unsigned byte=0;byte<4;++byte)ownedWave[offset+byte]=uint8_t(value>>(byte*8));};writeU32(4,uint32_t(ownedWave.size()-8));writeU32(40,uint32_t(LargeSampleBytes));uint8_t* const ownedStorage=ownedWave.data();AudioLoadResult ownedLoaded=LoadWave(std::move(ownedWave));if(!ownedLoaded||ownedLoaded.clip.samples.data()!=ownedStorage||ownedLoaded.clip.samples.size()!=LargeSampleBytes||ownedLoaded.clip.samples.capacity()<LargeSampleBytes){std::cerr<<"Owned WAVE storage was not reused\n";return 19;}const std::filesystem::path wavePath=std::filesystem::temp_directory_path()/("AevryndAudioTest-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count())+".wav");{std::ofstream output(wavePath,std::ios::binary);output.write(reinterpret_cast<const char*>(wave.data()),std::streamsize(wave.size()));if(!output){std::cerr<<"Temporary WAVE creation failed\n";return 20;}}AudioLoadResult fileLoaded=LoadWaveFile(wavePath);std::error_code removeError;std::filesystem::remove(wavePath,removeError);if(!fileLoaded||fileLoaded.clip.samples!=loaded.clip.samples){std::cerr<<"Sized WAVE file loading failed\n";return 21;}
    std::array<uint8_t,52> invalid=wave;invalid[20]=3;if(LoadWave(invalid)){std::cerr<<"Unsupported WAVE format was accepted\n";return 2;}invalid=wave;invalid[40]=9;if(LoadWave(invalid)){std::cerr<<"Misaligned WAVE data was accepted\n";return 3;}
    AudioClip tone=GenerateTone(440,.05f,.25f,48000);if(!tone.Valid()||tone.FrameCount()!=2400||tone.DurationSeconds()<.049f||tone.DurationSeconds()>.051f||std::all_of(tone.samples.begin(),tone.samples.end(),[](uint8_t sample){return sample==0;})){std::cerr<<"Procedural tone generation failed\n";return 4;}
    const AudioPlayback spatial2D=CalculateSpatialAudio(AudioSpatial2D{{}, {400,0},800,1,1,1}),spatial3D=CalculateSpatialAudio(AudioSpatial3D{{}, {1,0,0}, {-10,0,0},20,1,1,1});if(std::abs(spatial2D.volume-.5f)>.001f||std::abs(spatial2D.pan-.5f)>.001f||std::abs(spatial3D.volume-.5f)>.001f||spatial3D.pan!=-1.f){std::cerr<<"Spatial audio calculation failed\n";return 13;}AudioEngine audio;SoundH
